// PROJETO SM3 — TRIAGE QUEUE CONTRACT
// Only ANALYSIS_STATUS=QUEUED + ONLINE is eligible.
// If there is no work, emit one explicit NO_WORK sentinel so the execution
// communicates "nothing pending" instead of silently stopping.

const rows = $input.all().map(i => i.json);

const eligible = rows.filter(r =>
  String(r.ANALYSIS_STATUS || '').trim().toUpperCase() === 'QUEUED' &&
  String(r.STORAGE_STATUS || '').trim().toUpperCase() === 'ONLINE' &&
  String(r.PROCESS_STATUS || '').trim().toUpperCase() !== 'DEAD_LETTER'
);

if (eligible.length === 0) {
  return [{
    json: {
      queue_empty: true,
      analysis_route: 'NO_WORK',
      queued_for_analysis_at: new Date().toISOString()
    }
  }];
}

return eligible.map(r => {
  const type = String(r.TIPO || '').trim().toUpperCase();

  const route =
    type === 'FOTO' ? 'IMAGE_ORIGINAL' :
    type === 'VÍDEO' || type === 'VIDEO' ? 'VIDEO_PROXY' :
    'UNSUPPORTED';

  return {
    json: {
      ...r,
      queue_empty: false,
      analysis_route: route,
      analysis_source_planned:
        route === 'IMAGE_ORIGINAL' ? 'ORIGINAL' :
        route === 'VIDEO_PROXY' ? 'PROXY' : '',
      proxy_required: route === 'VIDEO_PROXY',
      queued_for_analysis_at: new Date().toISOString()
    }
  };
});

const all = $input.all().map(i => i.json);
const items = all.filter(x => !x.queue_empty);

const summary = {
  queue_empty: items.length === 0,
  queued_total: items.length,
  image_original: items.filter(x => x.analysis_route === 'IMAGE_ORIGINAL').length,
  video_proxy: items.filter(x => x.analysis_route === 'VIDEO_PROXY').length,
  unsupported: items.filter(x => x.analysis_route === 'UNSUPPORTED').length,
  projects: {}
};

for (const x of items) {
  const p = x.ID_PROJETO || 'NO_PROJECT';
  summary.projects[p] = (summary.projects[p] || 0) + 1;
}

return [{
  json: {
    dry_run: false,
    summary,
    queued_ids: items.map(x => x.ID_MIDIA),
    queue: items
  }
}];

return $input.all().map(i => ({
  json: {
    media_id: i.json.media_id,
    project_id: i.json.project_id,
    row_number: i.json.row_number,
    provider: i.json.provider,
    model: i.json.model,
    analysis: i.json.analysis,
    analysis_path: i.json.analysis_path,
    dry_run: true
  }
}));

return $input.all().map(i => ({
