const ANALYSIS_SOURCE = 'IMAGE_PROXY';

const now = new Date().toISOString();
const items = $input.all().map(i => i.json);

const workerByMedia = new Map(
  $('WORKER — PROCESS IMAGE').all().map(i => [String(i.json.media_id || ''), i.json])
);


function numericScore(v, field) {
  const n = Number(v);
  if (!Number.isFinite(n) || n < 0 || n > 100) {
    throw new Error(`ANALYSIS_WRITE_BLOCK: invalid ${field}=${v}`);
  }
  return n;
}

function normalizeScoreSet(a) {
  const raw = {
    editorial_score: numericScore(a.editorial_score, 'editorial_score'),
    technical_score: numericScore(a.technical_score, 'technical_score'),
    composition_score: numericScore(a.composition_score, 'composition_score'),
    tattoo_visibility: numericScore(a.tattoo_visibility, 'tattoo_visibility'),
    confidence: numericScore(a.confidence, 'confidence')
  };

  const visualFour = [
    raw.editorial_score,
    raw.technical_score,
    raw.composition_score,
    raw.tattoo_visibility
  ];

  // Strong evidence that the model accidentally used a 0–10 scale:
  // at least 3 of the 4 core scores are >0 and <=10.
  const lowCount = visualFour.filter(v => v > 0 && v <= 10).length;
  const detected10 = lowCount >= 3;

  const normalize = (v) => detected10 && v > 0 && v <= 10 ? v * 10 : v;

  return {
    editorial_score: Math.round(normalize(raw.editorial_score)),
    technical_score: Math.round(normalize(raw.technical_score)),
    composition_score: Math.round(normalize(raw.composition_score)),
    tattoo_visibility: Math.round(normalize(raw.tattoo_visibility)),
    confidence: Math.round(
      detected10 && raw.confidence > 0 && raw.confidence <= 10
        ? raw.confidence * 10
        : raw.confidence
    ),
    scale_detected: detected10 ? '10_NORMALIZED' : '100',
    normalization: detected10 ? 'X10_FROM_0_10' : 'NONE'
  };
}

const allowedSelection = new Set(['DESCARTAR', 'ANALISADO', 'SELECIONADO']);
const allowedQuality = new Set(['BAIXA', 'MEDIA', 'ALTA']);

return items.map(x => {
  const a = x.analysis || {};

  const w = workerByMedia.get(String(x.media_id || '')) || {};
  const meta = w.metadata || {};


  if (!x.row_number || !x.media_id || !x.project_id) {
    throw new Error(`ANALYSIS_WRITE_BLOCK: missing row/media/project identity`);
  }
  if (!x.provider || !x.model) {
    throw new Error(`ANALYSIS_WRITE_BLOCK: missing provider/model for ${x.media_id}`);
  }
  if (!allowedSelection.has(String(a.selection || '').toUpperCase())) {
    throw new Error(`ANALYSIS_WRITE_BLOCK: invalid selection for ${x.media_id}`);
  }
  if (!allowedQuality.has(String(a.quality || '').toUpperCase())) {
    throw new Error(`ANALYSIS_WRITE_BLOCK: invalid quality for ${x.media_id}`);
  }
  if (!String(a.visual_summary || '').trim()) {
    throw new Error(`ANALYSIS_WRITE_BLOCK: empty visual_summary for ${x.media_id}`);
  }

  const scores = normalizeScoreSet(a);
  const recommended = Array.isArray(a.recommended_use) ? a.recommended_use : [];

  const s = a.structure || {};
  const anatomy = s.anatomy || {};
  const tattoo = s.tattoo || {};
  const framing = s.framing || {};
  const crops = s.crops || {};

  const structuralConfidence = Number(s.structural_confidence);
  if (!Number.isFinite(structuralConfidence) || structuralConfidence < 0 || structuralConfidence > 100) {
    throw new Error(`ANALYSIS_WRITE_BLOCK: invalid structural_confidence for ${x.media_id}`);
  }

  const requiredStructural = [
    s.geometry_mode,
    anatomy.body_region,
    anatomy.view_angle,
    tattoo.orientation,
    tattoo.subject_primary,
    tattoo.stage,
    tattoo.coverage,
    tattoo.composition_shape,
    framing.focal_description
  ];
  if (requiredStructural.some(v => !String(v || '').trim())) {
    throw new Error(`ANALYSIS_WRITE_BLOCK: incomplete structural vision for ${x.media_id}`);
  }

  const cropGuidance = {
    reel_9x16: crops.reel_9x16 || {},
    story_9x16: crops.story_9x16 || {},
    feed_4x5: crops.feed_4x5 || {},
    square_1x1: crops.square_1x1 || {},
    landscape_16x9: crops.landscape_16x9 || {}
  };

  const formatFit = Object.fromEntries(
    Object.entries(cropGuidance).map(([k, v]) => [k, {
      viability_score: v.viability_score,
      strategy: v.strategy,
      anchor: v.anchor,
      rect_reliability: v.rect_reliability,
      rationale: v.rationale
    }])
  );


  return {
    json: {
      ID_MIDIA: x.media_id,
      ID_PROJETO: x.project_id,

      TRIAGEM: String(a.selection).toUpperCase(),
      QUALIDADE: String(a.quality).toUpperCase(),
      'CONTEÚDO_VISUAL': String(a.visual_summary || '').trim(),
      MELHOR_TRECHO: ANALYSIS_SOURCE === 'VIDEO_CONTACT_SHEET'
        ? String(a.best_moment || '').trim()
        : '',
      USAR_EM: recommended.join(', '),

      ANALYSIS_STATUS: 'ANALYZED',
      ANALYSIS_VERSION: 'SM3_TRIAGE_V4_HARDENED',
      ANALYSIS_SOURCE: ANALYSIS_SOURCE,
      VISION_PROVIDER: x.provider,
      VISION_MODEL: x.model,
      ANALYZED_AT: now,
      ANALYSIS_ERROR: '',
      PROCESS_STATUS: 'SUCCESS',
      RETRY_COUNT: 0,
      LAST_ATTEMPT_AT: now,
      LAST_ERROR_CODE: '',
      LAST_ERROR_MESSAGE: '',
      LAST_FAILURE_STAGE: '',
      LAST_FAILURE_NODE: '',
      NEXT_RETRY_AT: '',
      DEAD_LETTER_AT: '',
      DEAD_LETTER_ID: '',
      RELIABILITY_VERSION: 'SM3_RELIABILITY_V1',
      EDITORIAL_SCORE: scores.editorial_score,
      PROXY_STATUS: 'LOCAL_READY',

      ANALYSIS_STAGE: String(a.stage || '').toUpperCase(),
      SHOT_TYPE: String(a.shot_type || '').toUpperCase(),
      TECHNICAL_NOTES: String(a.technical_notes || '').trim(),
      TECHNICAL_SCORE: scores.technical_score,
      COMPOSITION_SCORE: scores.composition_score,
      TATTOO_VISIBILITY: scores.tattoo_visibility,
      ANALYSIS_CONFIDENCE: scores.confidence,
      REDUNDANCY_HINT: String(a.redundancy_hint || '').trim(),

      SCORE_SCALE_DETECTED: scores.scale_detected,
      SCORE_NORMALIZATION: scores.normalization,

      DATA_CAPTURA: String(meta.captured_at || ''),
      MIME_TYPE: String(meta.mime_type || ''),
      FILE_SIZE_BYTES: Number(meta.bytes || 0) || '',
      CONTENT_HASH: String(w.content_hash || meta.sha256 || ''),
      CAPTURED_AT_SOURCE: String(meta.captured_at_source || ''),
      TECHNICAL_METADATA_JSON: JSON.stringify(meta || {}),


      STRUCTURAL_ANALYSIS_VERSION: 'SM3_STRUCTURAL_V2',
      GEOMETRY_MODE: String(s.geometry_mode || '') === 'IMAGE_EXACT'
        ? 'IMAGE_SINGLE_FRAME_ESTIMATE'
        : String(s.geometry_mode || ''),
      BODY_REGION: String(anatomy.body_region || ''),
      BODY_SUBREGION: String(anatomy.body_subregion || ''),
      VIEW_ANGLE: String(anatomy.view_angle || ''),
      BODY_POSE: String(anatomy.body_pose || ''),
      TATTOO_ORIENTATION: String(tattoo.orientation || ''),
      TATTOO_STYLE_TAGS: Array.isArray(tattoo.style_tags) ? tattoo.style_tags.join(', ') : '',
      TATTOO_SUBJECT_PRIMARY: String(tattoo.subject_primary || ''),
      TATTOO_SUBJECT_TAGS: Array.isArray(tattoo.subject_tags) ? tattoo.subject_tags.join(', ') : '',
      TATTOO_STAGE_STRUCTURAL: String(tattoo.stage || ''),
      TATTOO_COVERAGE: String(tattoo.coverage || ''),
      COMPOSITION_SHAPE: String(tattoo.composition_shape || ''),
      FOCAL_DESCRIPTION: String(framing.focal_description || ''),
      FOCUS_POINT_NORM: JSON.stringify(framing.focus_point_norm || {}),
      TATTOO_BBOX_NORM: JSON.stringify(framing.tattoo_bbox_norm || {}),
      CROP_GUIDANCE_JSON: JSON.stringify(cropGuidance),
      FORMAT_FIT_JSON: JSON.stringify(formatFit),
      BEST_FORMATS: Array.isArray(s.best_formats) ? s.best_formats.join(', ') : '',
      STRUCTURAL_CONFIDENCE: Math.round(structuralConfidence),
      STRUCTURAL_NOTES: String(s.notes || '')
    }
  };
});

