const now = new Date().toISOString();
const maxTries = 3;
const workflow = 'PROJETO_SM3_02_TRIAGE_V8';

function compactError(x) {
  const e = x.error || x;
  const code = String(e.code || e.name || x.code || 'DRIVE_DOWNLOAD_FAILED').slice(0, 200);
  let msg = String(e.message || x.message || e.description || 'Terminal failure after retries.');
  if (msg.length > 4000) msg = msg.slice(0, 4000);
  return {code, msg};
}

