  const x = item.json || {};
  const mediaId = String(x.ID_MIDIA || x.media_id || x.MEDIA_ID || '').trim();
  const projectId = String(x.ID_PROJETO || x.project_id || x.PROJECT_ID || '').trim();
  const err = compactError(x);
  const suffix = Math.random().toString(36).slice(2, 8);
  const eventId = `DLQ_${Date.now()}_${mediaId || 'UNKNOWN'}_${suffix}`;

  return {json:{
    EVENT_ID: eventId,
    CREATED_AT: now,
    WORKFLOW: workflow,
    NODE: 'DOWNLOAD — ORIGINAL',
